const express = require('express')
const app = express()
app.get('/api/items', (req, res) => {
  const user = req.user
  if (!user || !user.permissions.includes("items:read")) return res.status(403).json({ error: "forbidden" })
  res.json({ ok: true })
})
app.listen(8080)

